    "arabic": " ((\u064a\u064f\u0635\u064e\u0644\u0651\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0628\u0650\u064a\u0651\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u064e\u0639\u0652\u062f\u064e \u0641\u064e\u0631\u064e\u0627\u063a\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u0625\u0650\u062c\u064e\u0627\u0628\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u064e\u0630\u0651\u0650\u0646\u0650)).",
