    "arabic": "\u0648\u0645\u0627 \u0646\u062f\u0645 \u0645\u0646 \u0627\u0633\u062a\u062e\u0627\u0631 \u0627\u0644\u062e\u0627\u0644\u0642 \u060c \u0648\u0634\u0627\u0648\u0631 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u064a\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u062a\u062b\u0628\u062a \u0641\u064a \u0623\u0645\u0631\u0647 \u060c \u0641\u0642\u062f \u0642\u0627\u0644 \u0633\u0628\u062d\u0627\u0646\u0647{ \u0648\u064e\u0634\u064e\u0627\u0648\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u0650 \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0639\u064e\u0632\u064e\u0645\u0652\u062a\u064e \u0641\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u0651\u0647\u0650} ",
