    "footnoteAr": "\u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629 \u060c \u0622\u064a\u0629 255 \u0645\u0646 \u0642\u0627\u0644\u0647\u0627 \u062d\u064a\u0646 \u064a\u0645\u0633\u064a \u0623\u062c\u064a\u0631 \u0645\u0646\u0647\u0645 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0623\u062e\u0631\u062c\u0647 \u0627\u0644\u062d\u0627\u0643\u0645 1/ 562\u0648\u0635\u062d\u062d\u0647 \u0627\u0644\u0623\u0644\u0628\u0627\u0646\u064a \u0641\u064a \u0635\u062d\u064a\u062d \u0627\u0644\u062a\u0631\u063a\u064a\u0628 \u0648\u0627\u0644\u062a\u0631\u0647\u064a\u0628 1/ 273 \u0648\u0639\u0632\u0627\u0647 \u0625\u0644\u0649 \u0627\u0644\u0646\u0633\u0627\u0626\u064a \u0648\u0627\u0644\u0637\u0628\u0631\u0627\u0646\u064a \u0648\u0642\u0627\u0644 : \u0648\u0625\u0633\u0646\u0627\u062f \u0627\u0644\u0637\u0628\u0631\u0627\u0646\u064a \u062c\u064a\u062f"
