    "number": 1,
    "arabic": "((\u0627\u0644\u0644\u0651\u064e\u0647\u064f\u0645\u0651\u064e \u0631\u0628\u0651\u064e \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0648\u064e\u0627\u062a\u0650 \u0627\u0644\u0633\u0651\u064e\u0628\u0652\u0639\u0650\u060c \u0648\u064e\u0631\u064e\u0628\u0651\u064e \u0627\u0644\u0652\u0639\u064e\u0631\u0652\u0634\u0650 \u0627\u0644\u0652\u0639\u064e\u0638\u0650\u064a\u0645\u0650\u060c \u0643\u064f\u0646\u0652 \u0644\u0650\u064a \u062c\u064e\u0627\u0631\u0627\u064b \u0645\u0650\u0646\u0652 \u0641\u064f\u0644\u0627\u064e\u0646\u0650 \u0628\u0652\u0646\u0650 \u0641\u064f\u0644\u0627\u064e\u0646\u064d\u060c \u0648\u064e\u0623\u064e\u062d\u0652\u0632\u064e\u0627\u0628\u0650\u0647\u0650 \u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0627\u064e\u0626\u0650\u0642\u0650\u0643\u064e\u060c \u0623\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0631\u064f\u0637\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0623\u064e\u062d\u064e\u062f\u064c \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0623\u064e\u0648\u0652 \u064a\u064e\u0637\u0652\u063a\u064e\u0649\u060c \u0639\u064e\u0632\u0651\u064e \u062c\u064e\u0627\u0631\u064f\u0643\u064e\u060c \u0648\u064e\u062c\u064e\u0644\u0651\u064e \u062b\u064e\u0646\u064e\u0627\u0624\u064f\u0643\u064e\u060c \u0648\u064e\u0644\u0627\u064e \u0625\u0650\u0644\u064e\u0647\u064e \u0625\u0650\u0644\u0627\u0651\u064e \u0623\u064e\u0646\u0652\u062a\u064e)).",
