    "id": "162",
    "categoryId": "condolence",
    "number": 1,
    "arabic": "((\u0625\u0650\u0646\u0651\u064e \u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0623\u064e\u062e\u064e\u0630\u064e\u060c \u0648\u064e\u0644\u064e\u0647\u064f \u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0637\u064e\u0649\u060c \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0628\u0650\u0623\u064e\u062c\u064e\u0644\u064d \u0645\u064f\u0633\u064e\u0645\u0651\u064e\u0649... \u0641\u064e\u0644\u0652\u062a\u064e\u0635\u0652\u0628\u0650\u0631\u0652 \u0648\u064e\u0644\u0652\u062a\u064e\u062d\u0652\u062a\u064e\u0633\u0650\u0628\u0652)). \u0648\u064e\u0625\u0650\u0646\u0652 \u0642\u064e\u0627\u0644\u064e: ((\u0623\u064e\u0639\u0652\u0638\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064e\u0643\u064e\u060c \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0639\u064e\u0632\u064e\u0627\u0621\u064e\u0643\u064e\u060c \u0648\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0644\u0650\u0645\u064e\u064a\u0651\u0650\u062a\u0650\u0643\u064e)) \u0641\u064e\u062d\u064e\u0633\u064e\u0646\u064c.",
