    "id": "163",
    "categoryId": "placing-the-deceased-in-the-grave",
    "number": 1,
    "arabic": "((\u0628\u0650\u0633\u0652\u0645\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0639\u064e\u0644\u064e\u0649 \u0633\u064f\u0646\u0651\u064e\u0629\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650)).",
