    "footnoteAr": "\u0623\u0628\u0648 \u062f\u0627\u0648\u062f 3/314\u0628\u0633\u0646\u062f \u0635\u062d\u064a\u062d \u0648\u0623\u062d\u0645\u062f \u0628\u0644\u0641\u0638 \u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0648\u0639\u0644\u0649 \u0645\u0644\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0633\u0646\u062f\u0647 \u0635\u062d\u064a\u062d"
