    "footnoteAr": "\u0627\u0644\u062d\u0627\u0643\u0645 \u0648\u0635\u062d\u062d\u0647 \u0648\u0648\u0627\u0641\u0642\u0647 \u0627\u0644\u0630\u0647\u0628\u064a 2/100 \u0648\u0627\u0628\u0646 \u0627\u0644\u0633\u0646\u064a \u0628\u0631\u0642\u0645 524\u0648\u062d\u0633\u0646\u0647 \u0627\u0644\u062d\u0627\u0641\u0638 \u0641\u064a \u062a\u062e\u0631\u064a\u062c \u0627\u0644\u0623\u0630\u0643\u0627\u0631 5/154 \u0642\u0627\u0644 \u0627\u0628\u0646 \u0628\u0627\u0632:\u0648\u0631\u0648\u0627\u0647 \u0627\u0644\u0646\u0633\u0627\u0626\u064a \u0628\u0625\u0633\u0646\u0627\u062f \u062d\u0633\u0646 . \u0627\u0646\u0638\u0631 \u062a\u062d\u0641\u0629 \u0627\u0644\u0623\u062e\u064a\u0627\u0631 \u0635 37"
