    "categoryId": "upon-receiving-pleasant-news",
    "number": 1,
    "arabic": "((\u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064f \u0623\u064e\u0645\u0652\u0631\u064c \u064a\u064e\u0633\u064f\u0631\u0651\u064f\u0647\u064f \u0623\u064e\u0648\u0652 \u064a\u064f\u0633\u064e\u0631\u0651\u064f \u0628\u0650\u0647\u0650 \u062e\u064e\u0631\u0651\u064e \u0633\u064e\u0627\u062c\u0650\u062f\u0627\u064b \u0634\u064f\u0643\u0652\u0631\u0627\u064b \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649)).",
